from pathlib import Path
import html
import numpy as np,pandas as pd
def _table(df):return '\n'.join(['| '+' | '.join(map(str,df.columns))+' |','| '+' | '.join(['---']*len(df.columns))+' |']+['| '+' | '.join(str(v).replace('|','/') for v in r)+' |' for r in df.itertuples(index=False,name=None)])
def export_report(out,bundle,dec,coupling,qc,c):
 cov=bundle.coverage.reset_index(names='program_id');cols=[k for k in ['program_id','n_reference_genes','n_mapped_genes','mapping_retention','n_present_genes','n_detected_genes','coverage','detection_coverage','scoring_eligible','median_cell_detected_members','fraction_cells_zero_members'] if k in cov]
 distributions=bundle.scores.describe(percentiles=[.25,.5,.75]).T[['count','mean','std','min','25%','50%','75%','max']].reset_index(names='program_id')
 summary=coupling[coupling.pair_id.isin(c.get('selected_pairs',[]) or ['C01','C03','C04'])][['sample_id','coarse_identity','pair_id','n_total','spearman','adjusted_association','gene_overlap_n','binary_status','joint_fraction','lift','OR']]
 lines=['# MuMoMac 统一分析报告',f"输入：{c['species']}；{c['modality']}。输入 {qc['n_input']:,} 个观测，选入 {qc['n_selected']:,} 个；{qc['n_sample_records']} 个样本记录，{qc['n_confirmed_biological_units']} 个已确认来源内生物学单位。",'本报告为转录特征的描述性研究输出。未知动物/供体不按样本号推定；不进行疾病效应检验。',f"筛选依据：用户提供列 `{c.get('cell_type_column','provided scores')}`，标签 `{c.get('target_labels','inherited')}`；原始注释及来源字段保留在 cell_metadata.parquet。",'## 程序覆盖率与检测',_table(cov[cols]),'## 原始分数分布（未做跨研究绝对均值校准）',_table(distributions.round(6)),'## 连续优先表示',_table(dec[['program_id','auto_representation','decision_reasons']]),'A01 始终为连续活性协变量。L01–L05 有身份适用范围；L04 为 Monocyte-to-macrophage transition-associated feature，不等同于成熟轨迹。Continuous Preferred 代表没有充分的可靠分组证据，不证明只有单峰。',f"校准范围：{c.get('representation',{}).get('calibration',{}).get('scope','all_query')}。J_soft：{'明确请求，探索性' if c.get('include_joint_index') else '未请求'}；高尾曲线：{'明确请求，探索性' if c.get('include_tail') else '未请求'}。",'## 重点程序对',_table(summary.round(6)),'连续关联反映同一样本和身份内的共同变化。Adjusted association 为对深度等协变量作秩残差调整的关联，不是因果效应。共享基因风险见 gene_overlap_n / pairwise_gene_overlap.tsv；调整前后差异不能排除全部技术依赖。不同样本结果按样本分别保留，不将细胞数量作为生物学重复数。','Joint 为两个程序在同一观测中满足各自已声明高分规则；Relative-high 仅相对指定校准群体。没有完整二元规则时 Joint、Lift、OR 为 NA，仍可存在连续关联。共同高分、统计关联和分子协同是不同概念；J_soft 不等于相互作用概率。','## 质量、来源与限制','完整 QC：run_qc.json；各程序检测和不可评价原因见 program_coverage.tsv 与长表 QC。原始数值保留不表示程序在该身份/平台具有生物学解释。成员基因缺失不视为低分或阴性。']
 if c['species']=='human':lines+=['Human 为实验性同源扩展。旧 S 程序 BioMart 数据库 release 缺失，保留原冻结表及哈希；软件成功运行不代表跨物种功能认证。']
 if c['modality']=='cell_resolved_spatial':lines+=['输入为已分割细胞，原坐标按 cell_id 原样导出。RNA 核心以细胞观测适配，真实 modality 单列保留；这是工程兼容，未认证跨模态阈值。面板覆盖不足程序不可评价。本流程拒绝混合 spot 的单细胞 Mo/Mac 分析。']
 if 'condition_context_flag' in bundle.metadata:lines+=['来源上下文标记：'+str(bundle.metadata.condition_context_flag.value_counts().to_dict()),'膀胱历史 Naive 中包含991个 Ouyang WT tumour 细胞；WT 是肿瘤对照背景，不能据历史 Naive 标签认定健康正常参考。']
 lines+=['## 合并回原始对象','AnnData（严格按 ID 对齐，未选中细胞留空）：','```python','import pandas as pd','scores = pd.read_parquet("cell_program_scores.parquet").set_index("cell_id")','adata.obs = adata.obs.join(scores.reindex(adata.obs_names).add_prefix("MuMoMac_"))','# 空间：cell_coordinates.parquet 以 cell_id 连接；不重排或重建坐标。','```','Seurat（不要按行号拼接）：','```r','scores <- as.data.frame(arrow::read_parquet("cell_program_scores.parquet"))','rownames(scores) <- scores$cell_id','scores$cell_id <- NULL','seurat <- Seurat::AddMetaData(seurat, scores[colnames(seurat), , drop=FALSE])','```','版本与参数：software_versions.json、gene_set_manifest.json、ortholog_mapping_manifest.json、frozen_representation.json；所有结果仅对应本次输入和冻结规则。']
 md='\n\n'.join(lines)+'\n';(out/'MuMoMac_Report_ZH.md').write_text(md)
 # Self-contained report: true distributions shown as inline SVG interquartile ranges.
 bars=[]
 for row in distributions.itertuples(index=False,name=None):
  p,n,mean,sd,mi,q1,med,q3,ma=row
  if np.isfinite(med):bars.append(f'<div>{p} <svg width="260" height="18"><line x1="{10+220*mi}" y1="9" x2="{10+220*ma}" y2="9" stroke="#888"/><rect x="{10+220*q1}" y="4" width="{max(1,220*(q3-q1))}" height="10" fill="#9ecae1"/><line x1="{10+220*med}" y1="2" x2="{10+220*med}" y2="16" stroke="#111"/></svg></div>')
 (out/'MuMoMac_Report.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><title>MuMoMac Report</title><style>body{font-family:Arial,sans-serif;background:white;color:#222;max-width:1200px;margin:2em auto}pre{white-space:pre-wrap}svg{vertical-align:middle}table{border-collapse:collapse;font-size:12px}td,th{padding:4px;border:1px solid #ddd}.scroll{overflow:auto}</style><h1>MuMoMac Report</h1><p>Score distributions: range, interquartile interval, median; raw 0–1 scale.</p>'+''.join(bars)+'<h2>覆盖率与检测</h2><div class="scroll">'+cov[cols].to_html(index=False)+'<h2>连续优先表示</h2>'+dec[['program_id','auto_representation','decision_reasons']].to_html(index=False)+'<h2>样本内关联</h2>'+summary.to_html(index=False,na_rep='NA')+'</div><h2>完整说明、限制与合并示例</h2><pre>'+html.escape(md)+'</pre></html>')
